import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BarChartProps = Record<string, any>;

const BarChart: React.FC<BarChartProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "Monthly Revenue",
  subtitle = "Year to Date Growth",
  data = [
    { value: 35 },
    { value: 55 },
    { value: 85 },
    { value: 45 },
    { value: 95 },
    { value: 65 },
  ],
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Inter Tight", "Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Fixed visual constants to match the design
  const barWidth = 80;
  const chartHeight = 400;

  // Calculate max value for scaling
  const maxValue = Math.max(...data.map((d) => d.value));
  const chartMaxValue = maxValue * 1.1 || 100; // fallback to 100 if empty or 0

  // Container animation
  const containerSpring = spring({
    frame: frame - 10,
    fps,
    config: { damping: 200, stiffness: 100 },
    durationInFrames: 50,
  });

  // Title animation
  const titleSpring = spring({
    frame: frame - 20,
    fps,
    config: { damping: 200, stiffness: 120 },
    durationInFrames: 40,
  });

  const animationDelay = 0.5;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: "80px",
        fontFamily: "Inter, sans-serif",
        transition: "none",
      }}
    >
      <div
        style={{
          background: "linear-gradient(180deg, #2a2a2a 0%, #1a1a1a 100%)",
          borderRadius: "20px",
          padding: "60px 80px",
          width: "100%",
          maxWidth: "900px",
          opacity: containerSpring,
          transform: `scale(${interpolate(containerSpring, [0, 1], [0.95, 1])})`,
          boxShadow: "0 20px 60px rgba(0, 0, 0, 0.4)",
          border: "1px solid rgba(255, 255, 255, 0.1)",
        }}
      >
        {/* Text Section */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-start",
            marginBottom: "60px",
            opacity: titleSpring,
            transform: `translateY(${interpolate(titleSpring, [0, 1], [20, 0])}px)`,
          }}
        >
          <div style={{ flex: "1" }}>
            <h1
              style={{
                fontFamily: "Inter Tight, sans-serif",
                fontSize: "64px",
                fontWeight: "600",
                color: "#FFFFFF",
                margin: 0,
                marginBottom: "16px",
                letterSpacing: "-1.5px",
                lineHeight: "1.0",
              }}
            >
              {title}
            </h1>
            <p
              style={{
                fontFamily: "Inter Tight, sans-serif",
                fontSize: "32px",
                fontWeight: "500",
                color: "#8E8E93",
                margin: 0,
                letterSpacing: "-0.6px",
                lineHeight: "1.2",
              }}
            >
              {subtitle}
            </p>
          </div>
        </div>

        {/* Chart Container */}
        <div
          style={{
            width: "100%",
            height: chartHeight,
            position: "relative",
            display: "flex",
            alignItems: "flex-end",
            justifyContent: "space-between",
            paddingLeft: "20px",
            paddingRight: "20px",
          }}
        >
          {data.map((item, index) => {
            const barDelay = (animationDelay * fps) + (index * 8);
            const barSpring = spring({
              frame: frame - barDelay,
              fps,
              config: { damping: 300, stiffness: 100 },
              durationInFrames: 60,
            });

            const barHeight = (item.value / chartMaxValue) * chartHeight;
            // Ensure interpolation range is strictly monotonic and non-negative
            const safeBarHeight = Math.max(0, barHeight);
            const animatedHeight = interpolate(barSpring, [0, 1], [0, safeBarHeight]);

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                }}
              >
                <div
                  style={{
                    width: barWidth,
                    height: animatedHeight,
                    background: "linear-gradient(180deg, #666666 0%, #333333 100%)",
                    borderRadius: "12px",
                    opacity: barSpring,
                    boxShadow: "0 4px 16px rgba(0, 0, 0, 0.3)",
                    border: "1px solid rgba(255, 255, 255, 0.2)",
                  }}
                />
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default BarChart;